/*
 * Earthsonic — Temperature, high-quality smooth scan-to-sound edition
 * DROP-IN for audio/temperaturePlayer.js (compatible with the improved HTML).
 *
 * Data sources generated by scripts/process_temperature.py:
 *   ../data/processed/temperature/months.json
 *   ../data/processed/temperature/YYYY-MM.json
 *   ../data/processed/temperature/sonification_audit.json
 *
 * One bright west-to-east line. No dots. The high-resolution heatmap uses
 * mask-aware spatial smoothing + continuous interpolation of numeric NASA
 * anomalies. These are *display transformations*, never new observations.
 * The scanned color bands are derived from this exact displayed field.
 * Count of raster pixels per color changes the pitch of that color's note.
 */

const ROOT = "../data/processed/temperature/";
const DURATION = 24;                    // seconds for a complete global scan
// Fixed-resolution display/audio raster: reproducible pixel counts on every device.
// Larger than typical displayed map area; avoids magnifying the NASA 2° cells.
const RASTER_W = 2048;
const RASTER_H = 1024;
const HEAT_ALPHA = 165;                 // 0..255, soft translucent overlay
// Gaussian averaging on the *numeric source grid*, not a blur of colored blocks.
// ~2° original grid; sigma 1.1 source cells (~2.2°). Missing samples ignored.
const SOURCE_SMOOTH_SIGMA = 1.10;
const SOURCE_SMOOTH_BLEND = 0.86;        // retain some original local contrast
const MIN_INTERPOLATION_SUPPORT = 0.60;

// Fixed color stops for temperature ANOMALY relative to 1951–1980, in K / °C difference.
const STOPS = [
  [-5, [23, 52, 126]],
  [-3, [52, 125, 212]],
  [-1, [127, 209, 238]],
  [ 0, [244, 241, 223]],
  [ 1, [246, 209, 107]],
  [ 3, [242, 138, 61]],
  [ 5, [201, 45, 66]]
];

// Each color RANGE has one base note. The pixel count adds 0–12 semitones.
// Boundaries are the midpoints between the stops above. They never depend
// on browser scaling, transparency, or the decorative coastline overlay.
const COLOR_NOTES = [
  { name: "Deep blue",   max: -4.0, midi: 48, shape: "sine" },     // C3
  { name: "Blue",        max: -2.0, midi: 50, shape: "sine" },     // D3
  { name: "Cyan",        max: -0.5, midi: 53, shape: "triangle" }, // F3
  { name: "Ivory",       max:  0.5, midi: 55, shape: "sine" },     // G3
  { name: "Yellow",      max:  2.0, midi: 57, shape: "triangle" }, // A3
  { name: "Orange",      max:  4.0, midi: 60, shape: "sine" },     // C4
  { name: "Red",         max: Infinity, midi: 64, shape: "triangle" } // E4
];

const $ = id => document.getElementById(id);
const els = {
  month: $("month"), strip: $("monthStrip"), play: $("play"),
  restart: $("restart"), status: $("status"), heatmap: $("heatmap"),
  overlay: $("mapOverlay") || $("coast"), label: $("stageLabel"),
  seek: $("seek"), elapsed: $("elapsed"), total: $("total"),
  simrange: $("simrange"), date: $("metricDate") || $("date"),
  source: $("metricSource"), mean: $("metricMean") || $("anomaly"),
  audio: $("metricAudio") || $("region"), audit: $("audit")
};

const clamp = (x, a, b) => Math.min(b, Math.max(a, x));
const finite = x => typeof x === "number" && Number.isFinite(x);
const timeLabel = sec => `0:${String(Math.floor(clamp(sec, 0, DURATION))).padStart(2, "0")}`;
const months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
const heatCtx = els.heatmap.getContext("2d", { alpha: true });

const state = {
  catalog: [], data: null, month: null, provenance: null,
  colorRaster: null, rasterBands: null,
  audioContext: null, compressor: null, master: null, voices: [],
  playing: false, position: 0, startClock: 0, raf: 0,
  lastScanColumn: -1, lastInfoColumn: -1, loadVersion: 0,
  coastlineObjectUrl: null
};

function status(message, isError = false) {
  els.status.textContent = message;
  els.status.classList.toggle("error", isError);
}
async function json(path) {
  const response = await fetch(path);
  if (!response.ok) throw new Error(`Failed to fetch ${path} (${response.status})`);
  return response.json();
}
function colorBand(value) {
  for (let i = 0; i < COLOR_NOTES.length; i++) {
    if (value < COLOR_NOTES[i].max) return i;
  }
  return COLOR_NOTES.length - 1;
}
function colorAt(value) {
  const v = clamp(value, -5, 5);
  for (let i = 0; i < STOPS.length - 1; i++) {
    const [lo, a] = STOPS[i];
    const [hi, b] = STOPS[i + 1];
    if (v <= hi) {
      const t = clamp((v - lo) / (hi - lo), 0, 1);
      return [
        Math.round(a[0] + (b[0] - a[0]) * t),
        Math.round(a[1] + (b[1] - a[1]) * t),
        Math.round(a[2] + (b[2] - a[2]) * t)
      ];
    }
  }
  return STOPS[STOPS.length - 1][1];
}
function validateMonth(data, month) {
  if (data.month !== month || data.variable !== "tempanomaly" ||
      !Array.isArray(data.lat) || data.lat.length !== 90 ||
      !Array.isArray(data.lon) || data.lon.length !== 180 ||
      !Array.isArray(data.anomalies) || data.anomalies.length !== 90 ||
      !data.anomalies.every(row => Array.isArray(row) && row.length === 180)) {
    throw new Error("Unexpected JSON grid. Expected original 90×180 GISTEMP monthly export.");
  }
  for (let i = 0; i < 90; i++) {
    if (Math.abs(data.lat[i] - (-89 + 2 * i)) > 1e-5) throw new Error("Unexpected latitude centers");
  }
  for (let i = 0; i < 180; i++) {
    if (Math.abs(data.lon[i] - (-179 + 2 * i)) > 1e-5) throw new Error("Unexpected longitude centers");
  }
}

// --- Scientifically transparent display preprocessing ----------------------
// The ORIGINAL 90x180 values remain in data.anomalies, untouched. This
// mask-aware Gaussian averages only known neighbors and never inserts a value
// at a missing original grid center. Longitude wraps at +/-180; latitude does
// not wrap. Smoothing is a presentation choice, not a NASA measurement.
function makeDisplayField(data) {
  const kernel = [];
  for (let d = -2; d <= 2; d++) {
    kernel.push(Math.exp(-0.5 * (d / SOURCE_SMOOTH_SIGMA) ** 2));
  }
  const out = new Float32Array(90 * 180);
  out.fill(NaN);
  for (let y = 0; y < 90; y++) {
    const originalRow = 89 - y; // raster = north to south
    for (let x = 0; x < 180; x++) {
      const center = data.anomalies[originalRow][x];
      if (!finite(center)) continue; // no invention at missing NASA cells
      let total = 0;
      let support = 0;
      for (let dy = -2; dy <= 2; dy++) {
        const yy = y + dy;
        if (yy < 0 || yy >= 90) continue;
        for (let dx = -2; dx <= 2; dx++) {
          const xx = (x + dx + 180) % 180;
          const neighbor = data.anomalies[89 - yy][xx];
          if (!finite(neighbor)) continue;
          const weight = kernel[dx + 2] * kernel[dy + 2];
          total += weight * neighbor;
          support += weight;
        }
      }
      out[y * 180 + x] = center * (1 - SOURCE_SMOOTH_BLEND) +
        (support ? (total / support) : center) * SOURCE_SMOOTH_BLEND;
    }
  }
  return out;
}

// Bicubic B-spline kernel: C2-continuous numeric interpolation without the
// overshoots of an unconstrained cubic interpolator. Missing samples are
// excluded and normalized; support is tracked to fade data boundaries.
function bsplineWeight(x) {
  const a = Math.abs(x);
  if (a < 1) return (4 - 6 * a * a + 3 * a * a * a) / 6;
  if (a < 2) return (2 - a) ** 3 / 6;
  return 0;
}

// Precompute basis weights for the 2048x1024 raster (no allocations per pixel).
function makeAxisLookup(length, gridLength, wrap) {
  const positions = new Int16Array(length * 4);
  const weights = new Float32Array(length * 4);
  for (let p = 0; p < length; p++) {
    const coordinate = (p + 0.5) * gridLength / length - 0.5;
    const base = Math.floor(coordinate);
    for (let j = 0; j < 4; j++) {
      const position = base + j - 1;
      const offset = p * 4 + j;
      positions[offset] = wrap
        ? ((position % gridLength) + gridLength) % gridLength
        : clamp(position, 0, gridLength - 1);
      weights[offset] = bsplineWeight(coordinate - position);
    }
  }
  return { positions, weights };
}

// Palette uses fixed NASA anomaly thresholds, not arbitrary image RGB values.
// Numbers are the same interpolation as the live scan uses for note selection.
function writeColor(pixelBytes, offset, value, alpha) {
  const v = clamp(value, -5, 5);
  let index = 0;
  while (index < STOPS.length - 2 && v > STOPS[index + 1][0]) index++;
  const low = STOPS[index];
  const high = STOPS[index + 1];
  const t = clamp((v - low[0]) / (high[0] - low[0]), 0, 1);
  // A regular continuous ramp preserves the fixed anomaly-to-color mapping.
  pixelBytes[offset] = low[1][0] + (high[1][0] - low[1][0]) * t;
  pixelBytes[offset + 1] = low[1][1] + (high[1][1] - low[1][1]) * t;
  pixelBytes[offset + 2] = low[1][2] + (high[1][2] - low[1][2]) * t;
  pixelBytes[offset + 3] = alpha;
}

function renderSmoothHeatmap(data) {
  const field = makeDisplayField(data);
  const xLookup = makeAxisLookup(RASTER_W, 180, true);
  const yLookup = makeAxisLookup(RASTER_H, 90, false);
  const raster = document.createElement("canvas");
  raster.width = RASTER_W;
  raster.height = RASTER_H;
  const rc = raster.getContext("2d", { alpha: true });
  if (!rc) throw new Error("2D canvas is unavailable");
  const img = rc.createImageData(RASTER_W, RASTER_H);
  const bands = new Int8Array(RASTER_W * RASTER_H);
  bands.fill(-1);

  // We cache each value and coverage at a pixel. The audio scanner consults
  // this exact same raster's band IDs, so it never listens to off-screen cells.
  for (let y = 0; y < RASTER_H; y++) {
    const yi = y * 4;
    for (let x = 0; x < RASTER_W; x++) {
      const xi = x * 4;
      let sum = 0;
      let support = 0;
      // Only a handful of source cells are sampled at each rendered pixel.
      for (let j = 0; j < 4; j++) {
        const yw = yLookup.weights[yi + j];
        if (yw < 1e-8) continue;
        const row = yLookup.positions[yi + j] * 180;
        for (let i = 0; i < 4; i++) {
          const w = yw * xLookup.weights[xi + i];
          if (w < 1e-8) continue;
          const sample = field[row + xLookup.positions[xi + i]];
          if (!Number.isNaN(sample)) {
            sum += sample * w;
            support += w;
          }
        }
      }
      if (support < MIN_INTERPOLATION_SUPPORT) continue;

      const value = sum / support;
      // Fade missing-data edges, while excluding unsupported areas entirely.
      const fade = clamp((support - MIN_INTERPOLATION_SUPPORT) /
        (1 - MIN_INTERPOLATION_SUPPORT), 0, 1);
      const alpha = Math.round(HEAT_ALPHA * Math.pow(fade, 0.40));
      if (alpha < 12) continue;
      const pixel = y * RASTER_W + x;
      writeColor(img.data, pixel * 4, value, alpha);
      bands[pixel] = colorBand(value);
    }
  }
  rc.putImageData(img, 0, 0);

  // CSS scales the high-density raster down. Unlike the previous version,
  // there is NO blocky nearest-neighbor enlargement and NO heavy CSS blur.
  els.heatmap.width = RASTER_W;
  els.heatmap.height = RASTER_H;
  heatCtx.imageSmoothingEnabled = true;
  heatCtx.imageSmoothingQuality = "high";
  heatCtx.clearRect(0, 0, RASTER_W, RASTER_H);
  heatCtx.drawImage(raster, 0, 0);
  els.heatmap.style.imageRendering = "auto"; // override old 'pixelated' CSS
  els.heatmap.style.opacity = "0.88";
  els.heatmap.style.filter = "blur(0.65px) saturate(0.92)";
  state.colorRaster = raster;
  state.rasterBands = bands;
}

async function makeCoastlinesVisible() {
  if (!els.overlay) return;
  try {
    const src = els.overlay.getAttribute("src");
    const response = await fetch(src);
    if (!response.ok) throw new Error(`Map SVG returned ${response.status}`);
    const svg = new DOMParser().parseFromString(await response.text(), "image/svg+xml");
    if (svg.querySelector("parsererror")) throw new Error("Invalid map SVG");
    const backdrop = svg.documentElement.querySelector("rect");
    if (backdrop) backdrop.setAttribute("fill", "none");
    // Keep the actual geographical outlines while allowing temperature colors
    // to show through land areas. The original SVG has an opaque navy backdrop.
    for (const group of svg.documentElement.querySelectorAll("g")) {
      group.setAttribute("fill", "#113449");
      group.setAttribute("fill-opacity", "0.10");
      group.setAttribute("stroke", "#bcebe8");
      group.setAttribute("stroke-opacity", "0.92");
      group.setAttribute("stroke-width", "0.85");
    }
    const blob = new Blob([new XMLSerializer().serializeToString(svg)], {type: "image/svg+xml"});
    if (state.coastlineObjectUrl) URL.revokeObjectURL(state.coastlineObjectUrl);
    state.coastlineObjectUrl = URL.createObjectURL(blob);
    els.overlay.src = state.coastlineObjectUrl;
    els.overlay.style.opacity = "0.92";
    els.overlay.style.mixBlendMode = "normal";
    els.overlay.style.zIndex = "3";
    els.overlay.style.objectFit = "fill";
  } catch (error) {
    console.warn("Could not customize world map overlay:", error);
    els.overlay.style.opacity = "0.45";
    els.overlay.style.mixBlendMode = "screen";
  }
}

// Use an existing scanner canvas if present, otherwise create it in JS.
// IMPORTANT: no circles / markers — ONLY one vertical scanning line.
const stage = els.heatmap.parentElement;
const scanner = $("scanner") || document.createElement("canvas");
scanner.width = RASTER_W;
scanner.height = RASTER_H;
scanner.setAttribute("aria-label", "West-to-east audio scanner");
scanner.style.cssText = "position:absolute;inset:0;width:100%;height:100%;display:block;z-index:4;pointer-events:none;";
if (!scanner.parentNode) stage.appendChild(scanner);
if (els.label) els.label.style.zIndex = "5";
const scanCtx = scanner.getContext("2d", { alpha: true });

function drawScanner(seconds) {
  scanCtx.clearRect(0, 0, scanner.width, scanner.height);
  if (!state.playing || !state.data) return;
  const x = clamp(seconds / DURATION, 0, 1) * scanner.width;
  scanCtx.save();
  scanCtx.shadowColor = "rgba(90,247,224,0.75)";
  scanCtx.shadowBlur = 13;
  scanCtx.strokeStyle = "rgba(177,255,239,0.96)";
  scanCtx.lineWidth = 2.4;
  scanCtx.beginPath();
  scanCtx.moveTo(x, 0);
  scanCtx.lineTo(x, scanner.height);
  scanCtx.stroke();
  scanCtx.restore();
}

function scanColumn(seconds) {
  return clamp(Math.floor((clamp(seconds, 0, DURATION - 0.000001) / DURATION) * RASTER_W), 0, RASTER_W - 1);
}
function getColorCounts(column) {
  const counts = Array(COLOR_NOTES.length).fill(0);
  let valid = 0;
  for (let y = 0; y < RASTER_H; y++) {
    const bin = state.rasterBands[y * RASTER_W + column];
    if (bin >= 0) { counts[bin]++; valid++; }
  }
  return { counts, valid };
}
function noteName(midi) {
  const names = ["C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"];
  return names[midi % 12] + (Math.floor(midi / 12) - 1);
}
function pitchForPixels(color, count) {
  return color.midi + Math.round(12 * count / RASTER_H);
}
function hz(midi) {
  return 440 * Math.pow(2, (midi - 69) / 12);
}

// Seven gentle voices, each tied to one fixed color bin.
// Current color pixel counts drive BOTH pitch and loudness. No rhythmic loop,
// random note events, or precomputed regional note_events are played.
async function createAudio() {
  if (!state.audioContext) {
    const AudioContextCtor = window.AudioContext || window.webkitAudioContext;
    if (!AudioContextCtor) throw new Error("Web Audio is unavailable in this browser");
    state.audioContext = new AudioContextCtor();
    state.compressor = state.audioContext.createDynamicsCompressor();
    state.compressor.threshold.value = -18;
    state.compressor.knee.value = 14;
    state.compressor.ratio.value = 2.7;
    state.compressor.attack.value = 0.02;
    state.compressor.release.value = 0.18;
    state.master = state.audioContext.createGain();
    state.master.gain.value = 0.78;
    state.compressor.connect(state.master).connect(state.audioContext.destination);
  }
  await state.audioContext.resume();
  const now = state.audioContext.currentTime;
  for (let i = 0; i < COLOR_NOTES.length; i++) {
    const osc = state.audioContext.createOscillator();
    const gain = state.audioContext.createGain();
    osc.type = COLOR_NOTES[i].shape;
    osc.frequency.value = hz(COLOR_NOTES[i].midi);
    gain.gain.value = 0;
    osc.connect(gain).connect(state.compressor);
    osc.start(now);
    state.voices.push({ osc, gain });
  }
}
function stopAudio() {
  if (!state.audioContext) return;
  const now = state.audioContext.currentTime;
  for (const { osc, gain } of state.voices) {
    try {
      gain.gain.cancelScheduledValues(now);
      gain.gain.setTargetAtTime(0, now, 0.018);
      osc.stop(now + 0.10);
    } catch (_) { /* already stopped */ }
    osc.addEventListener("ended", () => {
      try { osc.disconnect(); gain.disconnect(); } catch (_) { /* released */ }
    }, { once: true });
  }
  state.voices = [];
}
function updateVoices(column) {
  if (!state.playing || !state.audioContext || !state.rasterBands) return;
  const { counts } = getColorCounts(column);
  const activeCount = counts.filter(n => n > 0).length;
  const now = state.audioContext.currentTime;
  for (let i = 0; i < state.voices.length; i++) {
    const { osc, gain } = state.voices[i];
    const pixels = counts[i];
    const share = pixels / RASTER_H;
    const targetMidi = pitchForPixels(COLOR_NOTES[i], pixels);
    // Soft portamento keeps rapid scanner motion musical, not clicky.
    osc.frequency.setTargetAtTime(hz(targetMidi), now, 0.045);
    const level = pixels === 0 ? 0 :
      (0.012 + 0.20 * Math.pow(share, 0.95)) / Math.sqrt(Math.max(1, activeCount / 2));
    gain.gain.setTargetAtTime(level, now, pixels ? 0.055 : 0.04);
  }
}
function playbackTime() {
  if (!state.playing || !state.audioContext) return state.position;
  return clamp(state.audioContext.currentTime - state.startClock, 0, DURATION);
}
function showScanAudit(seconds, force = false) {
  if (!state.rasterBands || !state.data) return;
  const col = scanColumn(seconds);
  if (!force && col === state.lastInfoColumn) return;
  state.lastInfoColumn = col;
  const { counts, valid } = getColorCounts(col);
  const lon = -180 + (col + 0.5) * 360 / RASTER_W;
  const sounding = COLOR_NOTES.map((color, i) => ({
    color: color.name,
    anomaly_bin_celsius: i === 0
      ? `below ${COLOR_NOTES[i].max}`
      : `${COLOR_NOTES[i - 1].max} to ${color.max === Infinity ? 'above' : color.max}`,
    scanned_pixel_count: counts[i],
    share_of_entire_scan_line_percent: +((counts[i] / RASTER_H) * 100).toFixed(2),
    base_note: noteName(color.midi),
    raised_semitones_from_pixel_count: Math.round(12 * counts[i] / RASTER_H),
    assigned_midi_note: counts[i] ? pitchForPixels(color, counts[i]) : null,
    audible_note: counts[i] ? noteName(pitchForPixels(color, counts[i])) : "silent"
  }));
  const prominent = sounding.filter(n => n.scanned_pixel_count)
    .sort((a, b) => b.scanned_pixel_count - a.scanned_pixel_count);
  if (els.audio) {
    els.audio.textContent = prominent.length
      ? prominent.slice(0, 3).map(n => `${n.color} ${n.audible_note} (${n.scanned_pixel_count}px)`).join(" · ")
      : "No temperature data under scanner";
  }
  if (els.audit) {
    els.audit.textContent = JSON.stringify({
      scientific_source: {
        dataset: state.data.dataset,
        dataset_url: state.data.dataset_url,
        source_file: state.data.source_file,
        source_sha256: state.data.source_sha256,
        selected_month: state.month,
        variable: "tempanomaly",
        units: "K anomaly (numerically identical to °C difference)",
        baseline: "1951–1980",
        original_grid: "90 × 180 cells at 2° resolution"
      },
      scanner: {
        playback_seconds: +seconds.toFixed(3),
        longitude_degrees: +lon.toFixed(3),
        color_raster_column: col,
        raster_height_pixels: RASTER_H,
        scanned_valid_pixels: valid,
        notes: sounding
      },
      reproducible_mapping: {
        color_bins_celsius: "[-∞,-4), [-4,-2), [-2,-0.5), [-0.5,0.5), [0.5,2), [2,4), [4,∞)",
        base_midi_notes: COLOR_NOTES.map(c => c.midi),
        pitch_rule: `MIDI = base MIDI + round(12 × scanned color pixels / ${RASTER_H})`,
        volume_rule: "Volume rises with that color's scan-line coverage; smoothed to avoid clicks",
        interpolation: "Mask-aware Gaussian on 2° anomalies (sigma 1.1 source cells, blend 0.86), followed by bicubic B-spline numeric interpolation; not new NASA observations",
        missing_values: "Transparent and silent",
        visual_audio_alignment: `Color counts are measured from the same ${RASTER_W}×${RASTER_H} smoothed and interpolated color raster displayed on the map`,
        scanner_audio_clock: "Web Audio AudioContext.currentTime",
        legacy_processor_note_events: "Not played; this version derives notes live from scanned color coverage",
        interpretation: "Color counts and pitches describe the smoothed high-resolution visualization, not independent raw NASA grid measurements"
      }
    }, null, 2);
  }
}
function updatePosition(seconds, force = false) {
  if (els.seek) els.seek.value = String(Math.round(seconds / DURATION * Number(els.seek.max || 1000)));
  if (els.elapsed) els.elapsed.textContent = timeLabel(seconds);
  showScanAudit(seconds, force);
}
function tick() {
  if (!state.playing) return;
  const seconds = playbackTime();
  const col = scanColumn(seconds);
  if (col !== state.lastScanColumn) {
    state.lastScanColumn = col;
    updateVoices(col);
  }
  drawScanner(seconds);
  updatePosition(seconds);
  if (seconds >= DURATION) {
    pause(true);
    return;
  }
  state.raf = requestAnimationFrame(tick);
}
function pause(ended = false) {
  if (state.playing) state.position = ended ? DURATION : playbackTime();
  state.playing = false;
  cancelAnimationFrame(state.raf);
  stopAudio();
  drawScanner(0);
  updatePosition(state.position, true);
  if (els.play) els.play.textContent = "▶ Play temperature + sound";
  if (state.data) status(ended ? "Scan finished" : "Paused");
}
async function play() {
  if (!state.data || !state.rasterBands || state.playing) return;
  if (state.position >= DURATION) state.position = 0;
  await createAudio();
  state.startClock = state.audioContext.currentTime - state.position;
  state.lastScanColumn = -1;
  state.playing = true;
  els.play.textContent = "❚❚ Pause";
  status("Scanning colors → notes · pitch follows color coverage");
  tick();
}
function restart() {
  pause();
  state.position = 0;
  updatePosition(0, true);
  status("Ready — press Play to start scanning");
}
function areaWeightedMean(data) {
  let total = 0, weightSum = 0;
  for (let y = 0; y < 90; y++) {
    const weight = Math.cos(data.lat[y] * Math.PI / 180);
    for (const v of data.anomalies[y]) {
      if (finite(v)) { total += v * weight; weightSum += weight; }
    }
  }
  return weightSum ? total / weightSum : null;
}
function makeMonthStrip() {
  if (!els.strip || !state.month) return;
  els.strip.replaceChildren();
  const year = state.month.slice(0, 4);
  const ready = new Set(state.catalog.map(m => m.month));
  for (let m = 1; m <= 12; m++) {
    const id = `${year}-${String(m).padStart(2, "0")}`;
    const button = document.createElement("button");
    button.className = "month";
    button.type = "button";
    button.textContent = months[m - 1];
    button.disabled = !ready.has(id);
    button.classList.toggle("ready", ready.has(id));
    button.classList.toggle("selected", id === state.month);
    button.classList.toggle("missing", !ready.has(id));
    if (!button.disabled) button.addEventListener("click", () => loadMonth(id));
    els.strip.appendChild(button);
  }
}
async function loadMonth(month) {
  const version = ++state.loadVersion;
  pause();
  state.position = 0;
  state.data = null;
  state.rasterBands = null;
  state.lastScanColumn = -1;
  state.lastInfoColumn = -1;
  els.play.disabled = true;
  els.restart.disabled = true;
  els.seek.disabled = true;
  status(`Loading NASA temperature anomalies for ${month}…`);
  try {
    const data = await json(`${ROOT}${month}.json`);
    if (version !== state.loadVersion) return;
    validateMonth(data, month);
    state.data = data;
    state.month = month;
    renderSmoothHeatmap(data);
    if (els.month) els.month.value = month;
    makeMonthStrip();
    if (els.label) els.label.textContent = `${month} · GISTEMP anomaly · color → note scan`;
    if (els.date) els.date.textContent = month;
    if (els.source) els.source.textContent = "NASA GISS GISTEMP v4";
    const mean = areaWeightedMean(data);
    if (els.mean) els.mean.textContent = mean === null ? "—" :
      `≈ ${mean >= 0 ? "+" : ""}${mean.toFixed(2)}°C (grid estimate)`;
    if (els.simrange) els.simrange.textContent = `${month} · scanning west → east`;
    if (els.total) els.total.textContent = timeLabel(DURATION);
    els.play.disabled = false;
    els.restart.disabled = false;
    els.seek.disabled = false;
    updatePosition(0, true);
    status(`Ready: ${month} · high-resolution blended heatmap · scan-to-sound`);
  } catch (error) {
    if (version !== state.loadVersion) return;
    console.error(error);
    if (els.label) els.label.textContent = "Temperature data failed to load";
    status(error.message, true);
  }
}

els.month.addEventListener("change", () => loadMonth(els.month.value));
els.play.addEventListener("click", () => {
  if (state.playing) pause();
  else play().catch(error => { pause(); status(error.message, true); });
});
els.restart.addEventListener("click", restart);
els.seek.addEventListener("input", () => {
  if (!state.data) return;
  const wasPlaying = state.playing;
  pause();
  state.position = clamp(Number(els.seek.value) / Number(els.seek.max || 1000), 0, 1) * DURATION;
  updatePosition(state.position, true);
  if (wasPlaying) play().catch(error => { pause(); status(error.message, true); });
});
window.addEventListener("beforeunload", () => {
  cancelAnimationFrame(state.raf);
  stopAudio();
  if (state.coastlineObjectUrl) URL.revokeObjectURL(state.coastlineObjectUrl);
});

(async function init() {
  try {
    status("Loading NASA GISS temperature months…");
    const [catalog, audit] = await Promise.all([
      json(`${ROOT}months.json`),
      json(`${ROOT}sonification_audit.json`)
    ]);
    if (!Array.isArray(catalog.months)) throw new Error("Invalid months.json catalog");
    state.catalog = catalog.months.map(m => typeof m === "string" ? { month: m } : m)
      .filter(m => /^\d{4}-\d{2}$/.test(m.month));
    state.provenance = audit;
    if (!state.catalog.length) throw new Error("No processed months available");
    els.month.replaceChildren();
    for (const entry of state.catalog) {
      const option = document.createElement("option");
      option.value = entry.month;
      option.textContent = entry.month;
      els.month.appendChild(option);
    }
    els.month.disabled = false;
    const foot = document.querySelector(".foot");
    if (foot) foot.textContent =
      "Scientific scope: NASA GISS GISTEMP v4 monthly temperature ANOMALIES, not absolute temperatures, " +
      "relative to 1951–1980. A lightly Gaussian-smoothed and bicubic-interpolated high-resolution " +
      "display is derived from the original 2° cells (not new observations). The scanner samples " +
      "this rendered field; each of seven " +
      "fixed anomaly-color ranges selects a base note, and its pixel count on the line raises " +
      "the note pitch. The sound is a reproducible artistic interpretation, not a NASA audio recording.";
    makeCoastlinesVisible();
    await loadMonth(state.catalog[0].month);
  } catch (error) {
    console.error(error);
    status(`${error.message}. Check data/processed/temperature/ files.`, true);
    if (els.audit) els.audit.textContent = String(error);
  }
})();
